declare module "*.py" {
  const source: string;
  export default source;
}

declare module "*.sh" {
  const source: string;
  export default source;
}

declare module "*.css" { const source: string; export default source; }
declare module "*.js" { const source: string; export default source; }
declare module "*.woff2" { const path: string; export default path; }
